use std::path::PathBuf;

/// Environment-driven config. Defaults mirror Proxmox: HTTPS on 0.0.0.0:8006.
pub struct Config {
    pub bind: String,
    pub port: u16,
    pub data_dir: PathBuf,
    /// Serve HTTPS with an autogenerated cert (default). The desktop app
    /// spawns the backend with `VIRT_MAN_WEB_LOOPBACK_HTTP=1` and its own
    /// data dir; loopback HTTP needs no TLS for the local webview.
    pub loopback_http: bool,
    /// Where the built SPA lives.
    pub dist_dir: PathBuf,
}

impl Config {
    pub fn load() -> Result<Self, String> {
        let bind = std::env::var("VIRT_MAN_WEB_BIND").unwrap_or_else(|_| "0.0.0.0".into());
        let port: u16 = std::env::var("VIRT_MAN_WEB_PORT")
            .unwrap_or_else(|_| "8006".into())
            .parse()
            .map_err(|e| format!("invalid VIRT_MAN_WEB_PORT: {e}"))?;
        let loopback_http = std::env::var("VIRT_MAN_WEB_LOOPBACK_HTTP")
            .map(|v| v == "1" || v == "true")
            .unwrap_or(false);

        let data_dir = match std::env::var("VIRT_MAN_WEB_DATA") {
            Ok(d) => PathBuf::from(d),
            Err(_) => {
                if unsafe { libc::geteuid() } == 0 {
                    PathBuf::from("/var/lib/virt-man")
                } else {
                    match std::env::var("XDG_DATA_HOME") {
                        Ok(d) => PathBuf::from(d).join("virt-man"),
                        Err(_) => {
                            PathBuf::from(std::env::var("HOME").unwrap_or_else(|_| "/tmp".into()))
                                .join(".local/share/virt-man")
                        }
                    }
                }
            }
        };

        let dist_dir = std::env::var("VIRT_MAN_WEB_DIST")
            .map(PathBuf::from)
            .unwrap_or_else(|_| {
                // Repo layout: web/server/.. = web/, dist at web/dist.
                let repo = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                    .parent()
                    .unwrap()
                    .join("dist");
                if repo.is_dir() {
                    return repo;
                }
                // Installed layout: /usr/local/share/virt-man/dist or /usr/share.
                for base in ["/usr/local/share/virt-man/dist", "/usr/share/virt-man/dist"] {
                    let p = PathBuf::from(base);
                    if p.is_dir() {
                        return p;
                    }
                }
                repo
            });

        Ok(Self {
            bind,
            port,
            data_dir,
            loopback_http,
            dist_dir,
        })
    }

    pub fn addr(&self) -> std::net::SocketAddr {
        format!("{}:{}", self.bind, self.port)
            .parse()
            .expect("invalid bind address")
    }

    pub fn cert_path(&self) -> PathBuf {
        self.data_dir.join("tls/cert.pem")
    }

    pub fn key_path(&self) -> PathBuf {
        self.data_dir.join("tls/key.pem")
    }
}
